dur=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nk=1:nw=1','data/input_video.mp4']).decode().strip())
segs=[]
for s in raw:
    a=float(s['start']); b=float(s['end'])
    if math.isnan(a) or math.isnan(b):
        continue
    a=max(0.0, min(a, dur))
    b=max(0.0, min(b, dur))
    if b-a<=1e-6:
        continue
    segs.append([a,b])
segs.sort()
merged=[]
for a,b in segs:
    if not merged:
        merged.append([a,b]); continue
    if a<=merged[-1][1]+1e-6:
        merged[-1][1]=max(merged[-1][1], b)
    else:
        merged.append([a,b])
final=[{'start':round(a,3),'end':round(b,3),'duration':round(b-a,3)} for a,b in merged]
out={'segments':final,'total_segments':len(final),'total_duration_seconds':round(sum(s['duration'] for s in final),3)}
json.dump(out, open('/root/all_segments.json','w'), indent=2)
print('video_duration_seconds', dur)
print('segments', len(final))
print('removed_seconds', out['total_duration_seconds'])
PY"}

